end

function tensor_matmul(a, b)
    a * b
end

function tensor_softmax(a, axis)
    exp.(a .- maximum(a, dims=axis)) ./ sum(exp.(a .- maximum(a, dims=axis)), dims=axis)
end

function tensor_transpose(a)
    permutedims(a)
end

function tensor_reshape(a, shape)
