end

function tensor_concat(a, b, axis)
    cat(a, b; dims=axis)
end

function tensor_split(a, n, axis)
    sz = size(a, axis)
    chunk = cld(sz, n)
    parts = Vector{SubArray{eltype(a), ndims(a), typeof(a), Tuple{Vararg{Union{UnitRange{Int}, Colon}, ndims(a)}}, true}}()
    start = 1
    for _ in 1:n
        stop = min(start + chunk - 1, sz)
        if start > sz
            break
        end
        idxs = [Colon() for _ in 1:ndims(a)]
        idxs[axis] = start:stop
        push!(parts, view(a, idxs...))
        start = stop + 1
    end
    parts
end

