end

function tensor_leaky_relu(a, alpha)
    max.(a, alpha .* a)
end

function tensor_elu(a, alpha)
    ifelse.(a .>= 0, a, alpha .* (exp.(a) .- 1))
end

function tensor_gelu(a)
    0.5 .* a .* (1 .+ erf.(a ./ sqrt(2)))
end

function tensor_layer_norm(a)
    m = mean(a)
    v = var(a)
    (a .- m) ./ sqrt(v + 1e-5)
end

function tensor_batch_norm(a; eps=1e-5)
    if ndims(a) == 1
        μ = mean(a)
        σ2 = var(a)
        return (a .- μ) ./ sqrt(σ2 + eps)
    elseif ndims(a) == 2
        μ = mean(a, dims=1)
        σ2 = var(a, dims=1)
        return (a .- μ) ./ sqrt.(σ2 .+ eps)
    else
        μ = mean(a, dims=1)
        σ2 = var(a, dims=1)
        return (a .- μ) ./ sqrt.(σ2 .+ eps)
    end
end

function tensor_dropout(a, rate)
    @assert 0.0 <= rate < 1.0
    mask = rand(size(a)...) .> rate
    a .* mask ./ (1 - rate)
end

function tensor_conv1d(input, kernel)
    n_valid = length(input) - length(kernel) + 1
    if n_valid <= 0
        return Float64[]
    end
    y = Vector{Float64}(undef, n_valid)
    k = reverse(kernel)
    @inbounds for i in 1:n_valid
        y[i] = dot(@view(input[i:i+length(k)-1]), k)
    end
    return y
end

function tensor_maxpool1d(input, size)
    last_start = length(input) - size + 1
    if last_start <= 0
        return Float64[]
    end
    out = Vector{Float64}()
    i = 1
    while i <= last_start
        push!(out, maximum(@view(input[i:i+size-1])))
        i += size
    end
    return out
end

function tensor_avgpool1d(input, size)
    last_start = length(input) - size + 1
    if last_start <= 0
        return Float64[]
    end
    out = Vector{Float64}()
    i = 1
    while i <= last_start
        push!(out, mean(@view(input[i:i+size-1])))
        i += size
    end
    return out
end

function tensor_lstm(x::Vector{Float64}, state::Tuple{Vector{Float64}, Vector{Float64}}, p::LSTMParams)
    h, c = state
    i = tensor_sigmoid(p.Wxi * x .+ p.Whi * h .+ p.bi)
    f = tensor_sigmoid(p.Wxf * x .+ p.Whf * h .+ p.bf)
    o = tensor_sigmoid(p.Wxo * x .+ p.Who * h .+ p.bo)
    g = tensor_tanh(p.Wxc * x .+ p.Whc * h .+ p.bc)
    c_new = f .* c .+ i .* g
    h_new = o .* tensor_tanh(c_new)
    return h_new, (h_new, c_new)
end

function tensor_gru(x::Vector{Float64}, h::Vector{Float64}, p::GRUParams)
    r = tensor_sigmoid(p.Wxr * x .+ p.Whr * h .+ p.br)
    z = tensor_sigmoid(p.Wxz * x .+ p.Whz * h .+ p.bz)
    n = tensor_tanh(p.Wxh * x .+ p.Whh * (r .* h) .+ p.bh)
    h_new = (1 .- z) .* h .+ z .* n
    return h_new
end

function tensor_embed(tokens, embedding)
    embedding[tokens, :]
end

function tensor_position_encode(seq, d)
    T = size(seq, 1)
    D = d
    pos = collect(0:T-1)
    i = collect(0:D-1)
    pos_mat = reshape(pos, T, 1)
    i_mat = reshape(i, 1, D)
    angles = pos_mat ./ (10000.0 .^ (i_mat ./ D))
    pe = zeros(T, D)
    pe[:, 1:2:end] .= sin.(angles[:, 1:2:end])
    if D >= 2
        pe[:, 2:2:end] .= cos.(angles[:, 2:2:end])
    end
    seq .+ pe
end

function run_reflective_tests()
    @testset "Reflective Tests" begin
        hidden = rand(Float64, 4096)
        output = rand(Float64, 4096)
        r = self_reflect(hidden, output)
        @test length(r) == 4096
        @test norm(r, 1) <= norm(hidden, 1) + 1e-8
        bytes = rand(UInt8, 1024)
        @test length(concept_patch(bytes, 0.1)) == 4096
        state = rand(Float64, 4096)
        @test photonic_interference(state, 0.0) ≈ state
        @test norm(photonic_interference(state, pi/2)) ≤ 1e-8 * length(state)
        tensor_a = rand(Float64, 4096)
        tensor_b = rand(Float64, 4096)
        @test length(phase_couple(tensor_a, tensor_b)) == 4096
        theta = rand(Float64, 4096)
        grad = rand(Float64, 4096)
        theta_before = copy(theta)
        meta_update!(theta, grad, 0.6, 0.3, 0.1)
        @test length(theta) == 4096
        @test !all(theta .== theta_before)
        @test verify_security("deadbeef") == true
        @test verify_security("xyz") == false
        @test check_harmony(1.0) == true
        vector = rand(Float64, 4096)
        ctx = init_context(vector, "test")
        @test length(ctx[1]) == 4096
        @test length(reasoning_update(vector, vector)) == 4096
        @test length(process_multimodal(vector, vector)) == 4096
        @test length(update_agent(vector, vector)) == 4096
        @test length(execute_plan(["a", "b"])) == 2
        tree = [("a", 1)]
        @test length(update_behavior_tree(tree, "b", 2)) == 2
        kb = ["entry1"]
        @test length(update_knowledge_base(kb, "entry2")) == 2
        @test verify_system(true, "test") == true
        rl = run_reflective_loop(vector, 3)
        @test length(rl) == 4096
        @test norm(rl, 1) <= norm(vector, 1) + 1e-8
        graph = [(vector, vector)]
        @test length(update_concept_graph(graph, vector, vector)) == 2
        @test update_meta_reasoning(vector, vector) |> length == 4096
        @test length(process_token_stream(Int[1,2,3,4,5])) == 4096
        @test sum(process_token_stream(Int[1,2,3,4,5])) == 5
        @test length(update_multimodal_state(vector, vector)) == 4096
        rgraph = [("label", vector)]
        @test length(update_reasoning_graph(rgraph, "label2", vector)) == 2
        @test check_security_invariant(vector) == true
        nonfinite = copy(vector); nonfinite[1] = Inf
        @test check_security_invariant(nonfinite) == false
        @test update_convergence_state(1.0, 0.5) == 1.5
        @test length(update_reflective_agent(vector, vector)) == 4096
        @test update_task_context("ctx", vector) == "ctx"
        kgraph = [("s1", "s2")]
        @test length(update_knowledge_graph(kgraph, "s3", "s4")) == 2
        @test length(run_reasoning_loop(vector, 1)) == 4096
        in_dim = 8
        hid_dim = 8
        x = randn(Float64, in_dim)
        h0 = randn(Float64, hid_dim)
        c0 = randn(Float64, hid_dim)
        lp = LSTMParams(randn(hid_dim, in_dim), randn(hid_dim, hid_dim), randn(hid_dim),
                        randn(hid_dim, in_dim), randn(hid_dim, hid_dim), randn(hid_dim),
                        randn(hid_dim, in_dim), randn(hid_dim, hid_dim), randn(hid_dim),
                        randn(hid_dim, in_dim), randn(hid_dim, hid_dim), randn(hid_dim))
        h1, (h1_, c1) = tensor_lstm(x, (h0, c0), lp)
        @test length(h1) == hid_dim
        @test length(h1_) == hid_dim
        @test length(c1) == hid_dim
        @test sum(abs.(h1 .- (h0 .+ x[1:hid_dim]))) > 1e-6
        gp = GRUParams(randn(hid_dim, in_dim), randn(hid_dim, hid_dim), randn(hid_dim),
                       randn(hid_dim, in_dim), randn(hid_dim, hid_dim), randn(hid_dim),
                       randn(hid_dim, in_dim), randn(hid_dim, hid_dim), randn(hid_dim))
        hg = tensor_gru(x, h0, gp)
        @test length(hg) == hid_dim
        @test sum(abs.(hg .- (h0 .+ x[1:hid_dim]))) > 1e-6
        a = randn(32, 16)
        bn = tensor_batch_norm(a)
        μ = mean(bn, dims=1)
        σ2 = var(bn, dims=1)
        @test all(abs.(μ) .< 1e-6)
        @test all(abs.(σ2 .- 1.0) .< 1e-4)
        v = randn(128)
        k = randn(7)
        conv1 = tensor_conv1d(v, k)
        conv2 = Vector{Float64}()
        kr = reverse(k)
        for i in 1:(length(v)-length(k)+1)
            push!(conv2, dot(@view(v[i:i+length(k)-1]), kr))
        end
        @test conv1 ≈ conv2
    end
end

